from pathlib import Path
import json
P=Path('/workspace/scratch/a5176e5b5d45/SA06_work/parts/cote15_middle')
I={int(x['id'].split('-')[-1]):x for x in json.loads((P/'items.json').read_text())}
C=[]; audit=[]
def c(n,ii,sc,ln,words,stmt,status,cl,fate,refs,proof,blocks=(),search=(),date='Classical statement; exact first circulation not established',confidence='high'):
    comp={'proof':f'parts/cote15_middle/proofs.md §P{proof}'}
    if blocks:comp.update(code='parts/cote15_middle/code/exact_checks.py',output='parts/cote15_middle/audit/exact_checks.json',checks=list(blocks))
    else:comp['required']='No numerical computation required; proof/hypothesis audit at the cited section.'
    C.append(dict(id=f'C-SA06-{n}',items=[f'SA06-{i}' for i in ii],cote='15',scans=sc,lines=ln,his_statement=words,statement=stmt,status_on_pages=status,computation=comp,**{'class':cl},fate=fate,fate_date=date,present_status='As of 2026-11-19: '+fate,refs=refs,confidence=confidence))
    audit.append(dict(claim_id=f'C-SA06-{n}',proof_section=proof,blocks=list(blocks),search_batches=list(search)))
def ci(n,ii,status,cl,fate,refs,proof,blocks=(),search=(),date='Classical statement; exact first circulation not established',confidence='high',stmt=None):
    if isinstance(ii,int):ii=[ii]
    base=I[ii[0]]
    scans=sorted(set(s for j in ii for s in I[j]['scans']))
    lines='; '.join('Pro '+I[j]['lines'] for j in ii)
    c(n,ii,scans,lines,base['his_words'],stmt or ' '.join(I[j]['statement'] for j in ii),status,cl,fate,refs,proof,blocks,search,date,confidence)

